SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
SSL_CTX_set_min_proto_version(ctx, TLS1_2_VERSION);
SSL_CTX_set_default_verify_paths(ctx);          /* system CA bundle */
SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, NULL);
SSL *ssl = SSL_new(ctx);
SSL_set_fd(ssl, fd);                            /* connected TCP socket */
SSL_set_tlsext_host_name(ssl, "www.example.com"); /* SNI */
SSL_set1_host(ssl, "www.example.com");          /* hostname check */
if (SSL_connect(ssl) != 1) { ERR_print_errors_fp(stderr); }
SSL_write(ssl, req, reqlen);
SSL_shutdown(ssl);                              /* sends close_notify */
